location = /ecorex-agent/usage-panel {
    return 301 /ecorex-agent/usage-panel/;
}
location ^~ /ecorex-agent/usage-panel/api/ {
location ^~ /ecorex-agent/usage-panel/api/ {
    auth_basic "EcoreX Usage Panel";
    auth_basic "EcoreX Usage Panel";
    auth_basic_user_file /etc/nginx/ecorex-usage-panel.htpasswd;
    auth_basic_user_file /etc/nginx/ecorex-usage-panel.htpasswd;
    proxy_pass http://127.0.0.1:18105/api/;
    proxy_pass http://127.0.0.1:18105/api/;
    proxy_http_version 1.1;
    proxy_http_version 1.1;
    proxy_set_header Host $host;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    add_header Cache-Control "no-store" always;
    add_header Cache-Control "no-store" always;
}
}






location ^~ /ecorex-agent/usage-panel/ {
location ^~ /ecorex-agent/usage-panel/ {
    auth_basic "EcoreX Usage Panel";
    auth_basic "EcoreX Usage Panel";
    auth_basic_user_file /etc/nginx/ecorex-usage-panel.htpasswd;
    auth_basic_user_file /etc/nginx/ecorex-usage-panel.htpasswd;
    alias /srv/ecorex-agent-usage-panel/current/;
    alias /srv/ecorex-agent-usage-panel/current/;
